"""Build the shared public Mexico experience from the reviewed host briefing."""
from pathlib import Path
import json
ROOT = Path(__file__).resolve().parents[1]
briefing = json.loads((ROOT / 'docs/content/trip-releases/mexico-january-2027-host-briefing.json').read_text(encoding='utf-8'))
photos = json.loads((ROOT / 'trips/mexico-city/photos.json').read_text(encoding='utf-8'))
code = "/* Generated by tools/build_mexico_host_content.py; public host briefing only. */\n(() => {\n"
code += ' const briefing=' + json.dumps(briefing, ensure_ascii=False, separators=(',', ':')) + ';\n'
code += ' const photos=' + json.dumps(photos, ensure_ascii=False, separators=(',', ':')) + ';\n'
code += r'''
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const photo=key=>photos.find(p=>p.key===key);
 const figure=p=>`<figure class="mexico-host-photo"><a href="${esc(p.src)}" target="_blank" rel="noopener" aria-label="Open full photo: ${esc(p.alt)}"><img src="${esc(p.src)}" width="${p.width}" height="${p.height}" alt="${esc(p.alt)}" loading="lazy"></a><figcaption>${esc(p.caption)}</figcaption></figure>`;
 function galleryHTML({compact=false}={}) {
  if(compact)return `<div class="mexico-photo-grid">${['outreach-meal-service','ranch-overview','lodging-twin-room'].map(key=>figure(photo(key))).join('')}</div>`;
  const groups=[...new Set(photos.map(p=>p.group))];
  return `<div class="mexico-gallery">${groups.map((group,i)=>`<details class="mexico-gallery-group" ${i===0?'open':''}><summary>${esc(group)} <span>${photos.filter(p=>p.group===group).length} photos</span></summary><div class="mexico-photo-grid">${photos.filter(p=>p.group===group).map(figure).join('')}</div></details>`).join('')}</div>`;
 }
 function scheduleHTML() {
  return `<ol class="mexico-host-schedule">${briefing.days.map(day=>`<li><details ${day.day===1?'open':''}><summary><span class="mexico-day-number">${String(day.day).padStart(2,'0')}</span><span><small>${esc(new Date(day.date+'T12:00:00Z').toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric',timeZone:'UTC'}))}</small><strong>${esc(day.title)}</strong></span></summary><div class="mexico-day-body"><p>${esc(day.summary)}</p><dl>${day.items.map(([time,text])=>`<div><dt>${esc(time)}</dt><dd>${esc(text)}</dd></div>`).join('')}</dl>${day.note?`<p class="mexico-planning-note">${esc(day.note)}</p>`:''}</div></details></li>`).join('')}</ol>`;
 }
 const matches=trip=>trip?.opportunity_id==='trip-mexico-city'||/^mexico city(?:,|$)/i.test(String(trip?.location||''));
 function create({traveler=false}={}) {
  const section=document.createElement('section');section.className='mexico-experience'+(traveler?' journey-section':' actual-trip-description');section.id='mexico-experience';
  section.innerHTML=`<p class="eyebrow">Meet the ministry. Picture the journey.</p><h2>Serve alongside God’s Kitchen.</h2><p>Join the local team for street outreach and practical work at Rancho Alfa y Omega. Shared meals, conversation, and a steady presence are at the heart of the ministry.</p>${galleryHTML({compact:true})}<div class="mexico-host-actions"><a class="button" href="/trips/mexico-city/gods-kitchen/">Meet God’s Kitchen <span aria-hidden="true">→</span></a><a class="text-link" href="/trips/mexico-city/#host-photos">See lodging, ranch &amp; transport photos <span aria-hidden="true">→</span></a></div><p class="mexico-planning-note"><strong>Proposed itinerary — subject to change.</strong> Read this journey’s daily itinerary for its dates and proposed activities. Plans, times, service assignments, and sightseeing may change before and during the journey as hosts respond to local needs, weather, transportation, and other conditions. Your leader will share updates.</p>${traveler?`<p>Ask your leader about this journey’s optional sightseeing allowance and final inclusions.</p><p>Confirm your room and bed assignment, bedding, accessibility needs, and ground-transport arrangements with your leader before travel. Photos illustrate the spaces and vehicles; they do not reserve a particular room or seat.</p>`:''}`;
  return section;
 }
 window.HSMexicoExperience={briefing,photos,matches,figure,galleryHTML,scheduleHTML,create,hero:photo('outreach-meal-service')};
})();
'''
(ROOT / 'trips/mexico-city/experience.js').write_text(code, encoding='utf-8')
print('Built shared Mexico briefing: six days and', len(photos), 'captioned photos.')
